$ErrorActionPreference='Continue'
$root='C:\Users\pc\SmartLedger-Build-Clean-20261010'; $out=Join-Path $root 'runtime_qa_screenshots'; Add-Type -AssemblyName System.Drawing; Add-Type -AssemblyName System.Windows.Forms; Add-Type -AssemblyName UIAutomationClient; Add-Type -AssemblyName UIAutomationTypes
function SaveShot([string]$name){ Start-Sleep -Milliseconds 800; $b=[System.Windows.Forms.Screen]::PrimaryScreen.Bounds; $bmp=New-Object System.Drawing.Bitmap($b.Width,$b.Height); $g=[System.Drawing.Graphics]::FromImage($bmp); $g.CopyFromScreen($b.Left,$b.Top,0,0,$b.Size); $p=Join-Path $out $name; $bmp.Save($p,[System.Drawing.Imaging.ImageFormat]::Png); $g.Dispose(); $bmp.Dispose(); Write-Output ('CAPTURED '+$p) }
function GetAppWindow { $all=[System.Windows.Automation.AutomationElement]::RootElement.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition); foreach($x in $all){try{if($x.Current.Name -match 'SmartLedger'){return $x}}catch{}}; return $null }
$log=[System.Collections.Generic.List[string]]::new(); $log.Add('## Interactive runtime follow-up '+(Get-Date -Format s)); $w=GetAppWindow
if($w){$log.Add('Initial app window: '+$w.Current.Name); $buttons=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,(New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty,[System.Windows.Automation.ControlType]::Button))); $did=$false; foreach($b in $buttons){try{$r=$b.Current.BoundingRectangle;if($r.X -gt 1000 -and $r.Width -gt 300 -and $r.Height -ge 45 -and $r.Height -le 65){$log.Add(('Invoking wide login-area button: name={0}; rect={1},{2},{3},{4}' -f $b.Current.Name,$r.X,$r.Y,$r.Width,$r.Height));$b.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke();$did=$true;break}}catch{$log.Add('Button invoke failed: '+$_.Exception.Message)}}; if(-not $did){$log.Add('No wide login-area button invoked.')} } else {$log.Add('FAIL: SmartLedger app window not found.')}
Start-Sleep -Seconds 5
SaveShot '02-after-login-attempt.png'
$w=GetAppWindow
if($w){$log.Add('Detected app root after attempt: '+$w.Current.Name); $cond=New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::IsControlElementProperty,$true); $els=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,$cond); $i=0; foreach($e in $els){if($i -ge 240){break}; try{$name=$e.Current.Name;$type=$e.Current.ControlType.ProgrammaticName;$r=$e.Current.BoundingRectangle;if($name -or $type -match 'Button|Edit|DataGrid|ComboBox|TabItem|ListItem|Window'){$log.Add(('- [{0}] {1} | enabled={2} | rect={3},{4},{5},{6}' -f $type,$name,$e.Current.IsEnabled,[math]::Round($r.X),[math]::Round($r.Y),[math]::Round($r.Width),[math]::Round($r.Height)));$i++}}catch{}}} else {$log.Add('No SmartLedger titled root detected after login attempt.')}
$log | Add-Content -Encoding UTF8 (Join-Path $root 'runtime-qa-initial-observations.txt'); Write-Output ('OBSERVATIONS_UPDATED '+$log.Count)
